{
     "title": "CSCI-99: Undergraduate Cooperative Education Seminar - Orientation Companion",
     "learningObjectives": [
       "Students will articulate the three core ethical responsibilities of computing professionals as defined by the ACM Code of Ethics.",
       "Students will explain how responsible technical communication requires distinguishing claims from evidence and accurately reporting research results.",
       "Students will identify the mandatory prerequisites and curricular requirements for registering for a Computer Science co-op program at RIT."
     ],
     "beats": [
       {
         "title": "Introduction to Co-op and Course Purpose",
         "claim": "The CSCI-99 seminar is a mandatory prerequisite for Computer Science students to register for co-operative education employment.",
         "example": "A second-year COMPSCI-BS student must complete this course before applying for a summer co-op position.",
         "visualDirection": "Display a simple flowchart showing 'CS Undergraduate' -> 'CSCI-99 Completion' -> 'Co-op Registration'.",
         "sourceIds": ["rit-csci-99"]
       },
       {
         "title": "Prerequisites and Eligibility",
         "claim": "Eligibility for this seminar is restricted to COMPSCI-BS or COMPEX-UND major students with at least second-year standing.",
         "example": "A first-year student cannot enroll until they have completed their introductory computer science courses.",
         "visualDirection": "Show a checklist graphic with three boxes: 'Major: COMPSCI-BS or COMPEX-UND', 'Standing: 2nd Year or Higher', 'Status: Enrolled'.",
         "sourceIds": ["rit-csci-99"]
       },
       {
         "title": "Course Schedule and Format",
         "claim": "The seminar is typically offered during Fall and Spring semesters and consists of a single lecture contact hour.",
         "example": "Students attend one 50-minute lecture session each semester to cover orientation and policy reviews.",
         "visualDirection": "Insert a calendar icon with two highlighted months: 'Fall' and 'Spring', alongside a clock icon labeled '1 Contact Hour'.",
         "sourceIds": ["rit-csci-99"]
       },
       {
         "title": "Co-op Preparation and Job Search",
         "claim": "Students will develop practical job search strategies and materials specifically tailored for computer science co-op employment.",
         "example": "Students draft a targeted resume and practice technical interview responses using industry-standard co-op application formats.",
         "visualDirection": "Show a split-screen graphic: left side displays a resume template, right side shows a mock interview checklist.",
         "sourceIds": ["rit-csci-99"]
       },
       {
         "title": "Career Services and Cooperative Education Overview",
         "claim": "Students are introduced to RIT’s Office of Career Services and Cooperative Education to understand institutional support structures.",
         "example": "Students learn how to access career counseling, co-op placement portals, and alumni networking resources.",
         "visualDirection": "Display a directory-style layout with icons for 'Career Counseling', 'Co-op Portal', and 'Alumni Network' under a central 'Office of Career Services' header.",
         "sourceIds": ["rit-csci-99"]
       },
       {
         "title": "Professional, Legal, and Ethical Responsibilities",
         "claim": "Students must understand the professional, legal, and ethical responsibilities that apply to co-op and subsequent professional experiences.",
         "example": "Students review confidentiality agreements and data handling protocols required by co-op employers.",
         "visualDirection": "Show a shield icon divided into three sections labeled 'Professional', 'Legal', and 'Ethical', with brief bullet points underneath each.",
         "sourceIds": ["rit-csci-99"]
       },
       {
         "title": "ACM Code of Ethics Foundations",
         "claim": "Computing professionals are directed to contribute to society, avoid harm, and maintain high standards of professional competence and ethical practice.",
         "example": "Students analyze a case study where a developer must choose between meeting a tight deadline and implementing robust security measures.",
         "visualDirection": "Display a circular diagram with arrows connecting 'Contribute to Society', 'Avoid Harm', 'Maintain High Standards', and 'Ethical Practice' to a central 'ACM Code' node.",
         "sourceIds": ["acm-code-of-ethics"]
       },
       {
         "title": "Ethical Decision-Making Framework",
         "claim": "Ethical computing decisions require identifying stakeholders, foreseeable benefits and harms, uncertainty, alternatives, and obligations.",
         "example": "Students map out a stakeholder impact chart for a proposed algorithm that processes user data, noting potential privacy risks and mitigation steps.",
         "visualDirection": "Show a flowchart starting with 'Identify Stakeholders' -> 'Assess Benefits/Harms' -> 'Evaluate Alternatives' -> 'Determine Obligations' -> 'Make Decision'.",
         "sourceIds": ["acm-code-of-ethics"]
       },
       {
         "title": "Responsible Technical Communication",
         "claim": "Responsible technical communication distinguishes claims from evidence, cites prior work, and reports results accurately without fabrication or falsification.",
         "example": "Students practice rewriting a draft abstract to separate empirical findings from theoretical hypotheses and add proper citations.",
         "visualDirection": "Display a side-by-side comparison: 'Before' shows a paragraph mixing claims and evidence; 'After' shows clearly separated sections with citation markers.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Research Integrity and Methodology",
         "claim": "Authors should preserve research integrity by describing methods well enough for evaluation, making limitations visible, and avoiding plagiarism.",
         "example": "Students draft a methodology section that explicitly states sample sizes, tools used, and known constraints of their experimental setup.",
         "visualDirection": "Show a checklist graphic with items: 'Methods Described for Evaluation', 'Limitations Disclosed', 'Plagiarism Avoided', 'Conflicts Disclosed'.",
         "sourceIds": ["acm-research-practice"]
       }
     ]
   }
